-- Generated by the Neutrino Translator from verified MLIR.
-- Idempotent + atomic (a function body runs in a single transaction).
CREATE OR REPLACE FUNCTION attest_core_scheme_settlement(p_settlement_id text)
RETURNS void
LANGUAGE plpgsql
AS $$
BEGIN
    IF EXISTS (SELECT 1 FROM coordination_status WHERE idempotency_key = p_settlement_id AND procedure = 'core_scheme_settlement' AND reconciled) THEN
        RAISE EXCEPTION 'bad transition';
    END IF;
    INSERT INTO coordination_status(procedure, idempotency_key, attested) VALUES ('core_scheme_settlement', p_settlement_id, true)
    ON CONFLICT (procedure, idempotency_key) DO UPDATE SET attested = true;
END;
$$;

CREATE OR REPLACE FUNCTION execute_core_scheme_settlement(p_settlement_id text, p_scheme_id text, p_bank_id text, p_treasury_id text, p_gross_position bigint, p_fee_bps bigint, p_currency text)
RETURNS void
LANGUAGE plpgsql
AS $$
DECLARE
    v_fee bigint;
    v_net bigint;
BEGIN
    IF EXISTS (SELECT 1 FROM coordination_status WHERE idempotency_key = p_settlement_id AND procedure = 'core_scheme_settlement' AND reconciled) THEN
        RAISE EXCEPTION 'replay';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM coordination_status WHERE idempotency_key = p_settlement_id AND procedure = 'core_scheme_settlement' AND attested) THEN
        RAISE EXCEPTION 'missing attestation';
    END IF;

    -- idempotency guard (replay-safe): one row per workflow key
    INSERT INTO posting_idempotency(idempotency_key, entry)
    VALUES (p_settlement_id, 'core_scheme_settlement')
    ON CONFLICT DO NOTHING;
    IF NOT FOUND THEN
        RETURN;  -- already processed; no double posting
    END IF;

    v_fee := ((p_gross_position * p_fee_bps) / 10000);
    v_net := (p_gross_position - v_fee);

    -- debit scheme_principal (scheme.net_payable)
    IF (v_net) < 0 THEN
        RAISE EXCEPTION 'negative money for scheme_principal';
    END IF;
    INSERT INTO ledger_balance(ledger, party, currency, balance)
    VALUES ('scheme.net_payable', p_scheme_id, p_currency, -(v_net))
    ON CONFLICT (ledger, party, currency)
    DO UPDATE SET balance = ledger_balance.balance + (-(v_net));
    INSERT INTO postings(procedure, entry, ledger, party, amount, currency, signed_amount, idempotency_key)
    VALUES ('core_scheme_settlement', 'scheme_principal', 'scheme.net_payable', p_scheme_id, v_net, p_currency, -(v_net), p_settlement_id);

    -- credit bank_principal (bank.settlement_account)
    IF (v_net) < 0 THEN
        RAISE EXCEPTION 'negative money for bank_principal';
    END IF;
    INSERT INTO ledger_balance(ledger, party, currency, balance)
    VALUES ('bank.settlement_account', p_bank_id, p_currency, v_net)
    ON CONFLICT (ledger, party, currency)
    DO UPDATE SET balance = ledger_balance.balance + (v_net);
    INSERT INTO postings(procedure, entry, ledger, party, amount, currency, signed_amount, idempotency_key)
    VALUES ('core_scheme_settlement', 'bank_principal', 'bank.settlement_account', p_bank_id, v_net, p_currency, v_net, p_settlement_id);

    -- debit scheme_fee (scheme.fee_payable)
    IF (v_fee) < 0 THEN
        RAISE EXCEPTION 'negative money for scheme_fee';
    END IF;
    INSERT INTO ledger_balance(ledger, party, currency, balance)
    VALUES ('scheme.fee_payable', p_scheme_id, p_currency, -(v_fee))
    ON CONFLICT (ledger, party, currency)
    DO UPDATE SET balance = ledger_balance.balance + (-(v_fee));
    INSERT INTO postings(procedure, entry, ledger, party, amount, currency, signed_amount, idempotency_key)
    VALUES ('core_scheme_settlement', 'scheme_fee', 'scheme.fee_payable', p_scheme_id, v_fee, p_currency, -(v_fee), p_settlement_id);

    -- credit treasury_fee (treasury.fee_income)
    IF (v_fee) < 0 THEN
        RAISE EXCEPTION 'negative money for treasury_fee';
    END IF;
    INSERT INTO ledger_balance(ledger, party, currency, balance)
    VALUES ('treasury.fee_income', p_treasury_id, p_currency, v_fee)
    ON CONFLICT (ledger, party, currency)
    DO UPDATE SET balance = ledger_balance.balance + (v_fee);
    INSERT INTO postings(procedure, entry, ledger, party, amount, currency, signed_amount, idempotency_key)
    VALUES ('core_scheme_settlement', 'treasury_fee', 'treasury.fee_income', p_treasury_id, v_fee, p_currency, v_fee, p_settlement_id);

    -- balanced invariant: this workflow key must net to zero
    IF (SELECT COALESCE(SUM(signed_amount), 0) FROM postings WHERE procedure = 'core_scheme_settlement' AND idempotency_key = p_settlement_id) <> 0 THEN
        RAISE EXCEPTION 'not balanced for %', p_settlement_id;
    END IF;

    INSERT INTO coordination_status(procedure, idempotency_key, reconciled) VALUES ('core_scheme_settlement', p_settlement_id, true)
    ON CONFLICT (procedure, idempotency_key) DO UPDATE SET reconciled = true;
END;
$$;
